package com.afaryn.kaoslab.data
import com.afaryn.kaoslab.model.ProductTemplate import com.afaryn.kaoslab.model.BusinessInsights import com.afaryn.kaoslab.model.ChartData import com.afaryn.kaoslab.model.Order import com.afaryn.kaoslab.model.OrderStatusCounts import com.afaryn.kaoslab.model.Transaction import com.afaryn.kaoslab.model.TransactionFilter import kotlinx.coroutines.flow.Flow
