package com.afaryn.kaoslab.ui_owner.sales

import android.app.DatePickerDialog
import android.os.Bundle
import androidx.fragment.app.Fragment
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import androidx.fragment.app.viewModels
import androidx.lifecycle.lifecycleScope
import androidx.recyclerview.widget.LinearLayoutManager
import com.afaryn.kaoslab.databinding.FragmentSalesRevenueOwnerBinding
import com.afaryn.kaoslab.model.TransactionType
import com.afaryn.kaoslab.ui_owner.sales.adapter.TransactionHistoryAdapter
import com.afaryn.kaoslab.utils.Response
import com.google.android.material.dialog.MaterialAlertDialogBuilder
import com.google.firebase.Timestamp
import dagger.hilt.android.AndroidEntryPoint
import kotlinx.coroutines.launch
import java.text.NumberFormat
import java.text.SimpleDateFormat
import java.util.*

@AndroidEntryPoint
class SalesRevenueOwnerFragment : Fragment() {

    private var _binding: FragmentSalesRevenueOwnerBinding? = null
    private val binding get() = _binding!!

    private val viewModel: SalesRevenueViewModel by viewModels()
    private lateinit var transactionAdapter: TransactionHistoryAdapter

    override fun onCreateView(
        inflater: LayoutInflater, container: ViewGroup?,
        savedInstanceState: Bundle?
    ): View {
        _binding = FragmentSalesRevenueOwnerBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)

        setupRecyclerView()
        setupClickListeners()
        observeViewModel()
    }

    private fun setupRecyclerView() {
        transactionAdapter = TransactionHistoryAdapter()
        binding.transactionRecyclerView.apply {
            adapter = transactionAdapter
            layoutManager = LinearLayoutManager(requireContext())
        }
    }

    private fun setupClickListeners() {
        binding.backArrow.setOnClickListener {
            requireActivity().onBackPressed()
        }

        binding.selectTypeButton.setOnClickListener {
            showTransactionTypeDialog()
        }

        binding.selectDateButton.setOnClickListener {
            showDateRangeDialog()
        }

        binding.withdrawButton.setOnClickListener {
            // Implement withdrawal functionality
            showWithdrawalDialog()
        }
    }

    private fun observeViewModel() {
        viewLifecycleOwner.lifecycleScope.launch {
            viewModel.totalBalance.collect { response ->
                when (response) {
                    is Response.Loading -> {
                        // Show loading state if needed
                    }
                    is Response.Success -> {
                        updateBalanceDisplay(response.data)
                    }
                    is Response.Error -> {
                        // Handle error
                    }
                    is Response.Idle -> {
                        // Initial state
                    }
                }
            }
        }

        viewLifecycleOwner.lifecycleScope.launch {
            viewModel.transactionHistory.collect { response ->
                when (response) {
                    is Response.Loading -> {
                        // Show loading state
                    }
                    is Response.Success -> {
                        transactionAdapter.submitList(response.data)
                    }
                    is Response.Error -> {
                        // Handle error
                    }
                    is Response.Idle -> {
                        // Initial state
                    }
                }
            }
        }

        viewLifecycleOwner.lifecycleScope.launch {
            viewModel.selectedTransactionType.collect { type ->
                updateTypeButtonText(type)
            }
        }

        viewLifecycleOwner.lifecycleScope.launch {
            viewModel.selectedDateRange.collect { dateRange ->
                updateDateButtonText(dateRange)
            }
        }
    }

    private fun updateBalanceDisplay(balance: Double) {
        val formatter = NumberFormat.getCurrencyInstance(Locale("id", "ID"))
        formatter.currency = Currency.getInstance("IDR")
        binding.totalBalanceAmount.text = formatter.format(balance).replace("IDR", "Rp")
    }

    private fun updateTypeButtonText(type: TransactionType?) {
        binding.selectTypeButton.text = when (type) {
            TransactionType.PAYMENT -> "Payment"
            TransactionType.WITHDRAWAL -> "Withdrawal"
            null -> "Select type"
        }
    }

    private fun updateDateButtonText(dateRange: Pair<Timestamp?, Timestamp?>) {
        if (dateRange.first != null && dateRange.second != null) {
            val sdf = SimpleDateFormat("dd/MM", Locale.getDefault())
            val startDate = sdf.format(dateRange.first!!.toDate())
            val endDate = sdf.format(dateRange.second!!.toDate())
            binding.selectDateButton.text = "$startDate - $endDate"
        } else {
            binding.selectDateButton.text = "Select Date"
        }
    }

    private fun showTransactionTypeDialog() {
        val options = arrayOf("All", "Payment", "Withdrawal")
        val currentSelection = when (viewModel.selectedTransactionType.value) {
            null -> 0
            TransactionType.PAYMENT -> 1
            TransactionType.WITHDRAWAL -> 2
        }

        MaterialAlertDialogBuilder(requireContext())
            .setTitle("Select Transaction Type")
            .setSingleChoiceItems(options, currentSelection) { dialog, which ->
                val selectedType = when (which) {
                    0 -> null
                    1 -> TransactionType.PAYMENT
                    2 -> TransactionType.WITHDRAWAL
                    else -> null
                }
                viewModel.setTransactionTypeFilter(selectedType)
                dialog.dismiss()
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun showDateRangeDialog() {
        val calendar = Calendar.getInstance()

        DatePickerDialog(
            requireContext(),
            { _, year, month, dayOfMonth ->
                val startDate = Calendar.getInstance()
                startDate.set(year, month, dayOfMonth, 0, 0, 0)

                // Show end date picker
                DatePickerDialog(
                    requireContext(),
                    { _, endYear, endMonth, endDayOfMonth ->
                        val endDate = Calendar.getInstance()
                        endDate.set(endYear, endMonth, endDayOfMonth, 23, 59, 59)

                        viewModel.setDateRangeFilter(
                            Timestamp(startDate.time),
                            Timestamp(endDate.time)
                        )
                    },
                    calendar.get(Calendar.YEAR),
                    calendar.get(Calendar.MONTH),
                    calendar.get(Calendar.DAY_OF_MONTH)
                ).apply {
                    setTitle("Select End Date")
                }.show()
            },
            calendar.get(Calendar.YEAR),
            calendar.get(Calendar.MONTH),
            calendar.get(Calendar.DAY_OF_MONTH)
        ).apply {
            setTitle("Select Start Date")
        }.show()
    }

    private fun showWithdrawalDialog() {
        // Basic withdrawal dialog - you can enhance this with amount input
        MaterialAlertDialogBuilder(requireContext())
            .setTitle("Withdrawal")
            .setMessage("Withdrawal functionality will be implemented here")
            .setPositiveButton("OK", null)
            .show()
    }

    override fun onDestroyView() {
        super.onDestroyView()
        _binding = null
    }
}

package com.afaryn.kaoslab.ui_owner.sales

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.afaryn.kaoslab.data.OwnerRepository
import com.afaryn.kaoslab.model.Transaction
import com.afaryn.kaoslab.model.TransactionFilter
import com.afaryn.kaoslab.model.TransactionType
import com.afaryn.kaoslab.utils.Response
import com.google.firebase.Timestamp
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import javax.inject.Inject

@HiltViewModel
class SalesRevenueViewModel @Inject constructor(
    private val ownerRepository: OwnerRepository
) : ViewModel() {

    private val _totalBalance = MutableStateFlow<Response<Double>>(Response.Idle)
    val totalBalance: StateFlow<Response<Double>> = _totalBalance.asStateFlow()

    private val _transactionHistory = MutableStateFlow<Response<List<Transaction>>>(Response.Idle)
    val transactionHistory: StateFlow<Response<List<Transaction>>> = _transactionHistory.asStateFlow()

    private val _selectedTransactionType = MutableStateFlow<TransactionType?>(null)
    val selectedTransactionType: StateFlow<TransactionType?> = _selectedTransactionType.asStateFlow()

    private val _selectedDateRange = MutableStateFlow<Pair<Timestamp?, Timestamp?>>(Pair(null, null))
    val selectedDateRange: StateFlow<Pair<Timestamp?, Timestamp?>> = _selectedDateRange.asStateFlow()

    init {
        getTotalBalance()
        getTransactionHistory()
    }

    fun getTotalBalance() {
        viewModelScope.launch {
            ownerRepository.getTotalBalance().collect { response ->
                _totalBalance.value = response
            }
        }
    }

    fun getTransactionHistory() {
        viewModelScope.launch {
            val filter = createTransactionFilter()
            ownerRepository.getTransactionHistory(filter).collect { response ->
                _transactionHistory.value = response
            }
        }
    }

    fun setTransactionTypeFilter(type: TransactionType?) {
        _selectedTransactionType.value = type
        getTransactionHistory()
    }

    fun setDateRangeFilter(startDate: Timestamp?, endDate: Timestamp?) {
        _selectedDateRange.value = Pair(startDate, endDate)
        getTransactionHistory()
    }

    fun clearFilters() {
        _selectedTransactionType.value = null
        _selectedDateRange.value = Pair(null, null)
        getTransactionHistory()
    }

    private fun createTransactionFilter(): TransactionFilter? {
        val type = _selectedTransactionType.value
        val dateRange = _selectedDateRange.value

        return if (type != null || (dateRange.first != null && dateRange.second != null)) {
            TransactionFilter(
                type = type,
                startDate = dateRange.first,
                endDate = dateRange.second
            )
        } else {
            null
        }
    }
}

package com.afaryn.kaoslab.ui_owner.sales.adapter

import android.view.LayoutInflater
import android.view.ViewGroup
import androidx.recyclerview.widget.DiffUtil
import androidx.recyclerview.widget.ListAdapter
import androidx.recyclerview.widget.RecyclerView
import com.afaryn.kaoslab.R
import com.afaryn.kaoslab.databinding.ItemTransactionHistoryBinding
import com.afaryn.kaoslab.model.Transaction
import com.afaryn.kaoslab.model.TransactionType
import java.text.NumberFormat
import java.text.SimpleDateFormat
import java.util.*

class TransactionHistoryAdapter : ListAdapter<Transaction, TransactionHistoryAdapter.TransactionViewHolder>(TransactionDiffCallback()) {

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): TransactionViewHolder {
        val binding = ItemTransactionHistoryBinding.inflate(
            LayoutInflater.from(parent.context),
            parent,
            false
        )
        return TransactionViewHolder(binding)
    }

    override fun onBindViewHolder(holder: TransactionViewHolder, position: Int) {
        holder.bind(getItem(position))
    }

    inner class TransactionViewHolder(
        private val binding: ItemTransactionHistoryBinding
    ) : RecyclerView.ViewHolder(binding.root) {

        fun bind(transaction: Transaction) {
            with(binding) {
                // Set transaction description
                transactionDescription.text = transaction.description

                // Format and set date
                transaction.createdAt?.let { timestamp ->
                    val sdf = SimpleDateFormat("dd - MM - yyyy", Locale.getDefault())
                    transactionDate.text = sdf.format(timestamp.toDate())
                } ?: run {
                    transactionDate.text = "Unknown Date"
                }

                // Format and set amount with color based on transaction type
                val formatter = NumberFormat.getCurrencyInstance(Locale("id", "ID"))
                formatter.currency = Currency.getInstance("IDR")

                when (transaction.type) {
                    TransactionType.PAYMENT -> {
                        transactionAmount.text = "+${formatter.format(transaction.amount).replace("IDR", "Rp")}"
                        transactionAmount.setTextColor(itemView.context.getColor(R.color.chocoTan))
                        // Use a simple drawable or color for the icon background
                        transactionIcon.setBackgroundResource(R.drawable.circle_background_gray)
                        transactionIcon.setImageResource(android.R.drawable.ic_menu_add)
                    }
                    TransactionType.WITHDRAWAL -> {
                        transactionAmount.text = "-${formatter.format(transaction.amount).replace("IDR", "Rp")}"
                        transactionAmount.setTextColor(itemView.context.getColor(android.R.color.holo_red_dark))
                        // Use a simple drawable or color for the icon background
                        transactionIcon.setBackgroundResource(R.drawable.circle_background_gray)
                        transactionIcon.setImageResource(android.R.drawable.ic_menu_delete)
                    }
                }
            }
        }
    }

    class TransactionDiffCallback : DiffUtil.ItemCallback<Transaction>() {
        override fun areItemsTheSame(oldItem: Transaction, newItem: Transaction): Boolean {
            return oldItem.id == newItem.id
        }

        override fun areContentsTheSame(oldItem: Transaction, newItem: Transaction): Boolean {
            return oldItem == newItem
        }
    }
}
